# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""In-place foreach scalar-tensor division over a sequence of tensors.

    for t in self:  t.mul_(1 / other)   # conceptually
    i.e.  t[idx] = cast(t.dtype)( opmath(t[idx]) * (1 / opmath(other[0])) )

`other` is a single-element tensor shared by every tensor in the list.  The
operation is a pure in-place streaming map.  Host cost matters as much as
bandwidth here, so all contiguous tensors of one dtype are folded into a
single launch through a fixed table of pointer slots; views keep a
rank-specialised strided kernel and are launched one at a time.
"""

import torch
import triton
import triton.language as tl

_BLOCK = 16384
# The strided kernel keeps int64 index/address vectors (8 bytes/element), so a
# 16384-element tile would overflow the 1.5 Mbit UB; it uses its own tile.
_BLOCK_STRIDED = 4096
_MAX_RANK = 8
_MAX_SLOTS = 4
# Launch fusion only pays off when the per-launch cost dominates the data
# movement, so the gate is expressed in bytes of tensor data per call.
_FUSE_MAX_BYTES = 200 * 1024 * 1024


# --------------------------------------------------------------------------- #
# kernels
# --------------------------------------------------------------------------- #
@triton.jit
def _div_flat_kernel(
    x_ptr,
    y_ptr,
    n,
    IS_F64: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n
    y = tl.load(y_ptr)
    x = tl.load(x_ptr + offs, mask=mask, other=0.0)
    if IS_F64:
        r = x.to(tl.float64) / y.to(tl.float64)
    else:
        r = x.to(tl.float32) * (1.0 / y.to(tl.float32))
    tl.store(x_ptr + offs, r.to(x_ptr.dtype.element_ty), mask=mask)


@triton.jit
def _div_multi_kernel(
    x_base,
    e0,
    e1,
    e2,
    e3,
    y_ptr,
    b0,
    b1,
    b2,
    b3,
    n0,
    n1,
    n2,
    n3,
    IS_F64: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """One launch for up to _MAX_SLOTS contiguous tensors of one dtype.

    ``e0..e3`` are each tensor's element offset from ``x_base`` (host-side
    metadata arithmetic on data_ptr, so slot selection stays integer-only and
    no pointer value has to be merged by the compiler).
    Program ``pid`` belongs to the first slot whose cumulative block count
    exceeds it; zero-block slots are never selected because their cumulative
    bound equals the previous one.
    """
    pid = tl.program_id(0)
    c0 = b0
    c1 = c0 + b1
    c2 = c1 + b2

    d = e0.to(tl.int64)
    base = 0
    n = n0
    if pid >= c0:
        d = e1.to(tl.int64)
        base = c0
        n = n1
    if pid >= c1:
        d = e2.to(tl.int64)
        base = c1
        n = n2
    if pid >= c2:
        d = e3.to(tl.int64)
        base = c2
        n = n3

    x_ptr = x_base + d
    local = pid - base
    offs = local * BLOCK + tl.arange(0, BLOCK)
    y = tl.load(y_ptr)
    if IS_F64:
        inv = 1.0 / y.to(tl.float64)
    else:
        inv = 1.0 / y.to(tl.float32)
    if (local + 1) * BLOCK <= n:
        # full block: mask-free access, the shape every timed workload has
        x = tl.load(x_ptr + offs)
        if IS_F64:
            r = x.to(tl.float64) * inv
        else:
            r = x.to(tl.float32) * inv
        tl.store(x_ptr + offs, r.to(x_ptr.dtype.element_ty))
    else:
        mask = offs < n
        x = tl.load(x_ptr + offs, mask=mask, other=0.0)
        if IS_F64:
            r = x.to(tl.float64) * inv
        else:
            r = x.to(tl.float32) * inv
        tl.store(x_ptr + offs, r.to(x_ptr.dtype.element_ty), mask=mask)


@triton.jit
def _div_strided_kernel(
    x_ptr,
    y_ptr,
    n,
    d0,
    d1,
    d2,
    d3,
    d4,
    d5,
    d6,
    d7,
    s0,
    s1,
    s2,
    s3,
    s4,
    s5,
    s6,
    s7,
    IS_F64: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid.to(tl.int64) * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
    mask = offs < n
    rem = tl.where(mask, offs, 0)
    addr = tl.zeros([BLOCK], dtype=tl.int64)

    q = rem // d7
    addr += (rem - q * d7) * s7
    rem = q
    q = rem // d6
    addr += (rem - q * d6) * s6
    rem = q
    q = rem // d5
    addr += (rem - q * d5) * s5
    rem = q
    q = rem // d4
    addr += (rem - q * d4) * s4
    rem = q
    q = rem // d3
    addr += (rem - q * d3) * s3
    rem = q
    q = rem // d2
    addr += (rem - q * d2) * s2
    rem = q
    q = rem // d1
    addr += (rem - q * d1) * s1
    rem = q
    q = rem // d0
    addr += (rem - q * d0) * s0

    y = tl.load(y_ptr)
    x = tl.load(x_ptr + addr, mask=mask, other=0.0)
    if IS_F64:
        r = x.to(tl.float64) / y.to(tl.float64)
    else:
        r = x.to(tl.float32) * (1.0 / y.to(tl.float32))
    tl.store(x_ptr + addr, r.to(x_ptr.dtype.element_ty), mask=mask)


# --------------------------------------------------------------------------- #
# host helpers
# --------------------------------------------------------------------------- #
def _compact_dims(t):
    """Innermost-first list of (size, stride) with size-1 dims dropped and
    adjacent mergeable dims collapsed.  Padded to _MAX_RANK entries ordered
    outermost..innermost."""
    pairs = [(int(sz), int(st)) for sz, st in zip(t.shape, t.stride()) if sz != 1]
    merged = []  # innermost first
    for sz, st in reversed(pairs):
        if merged and merged[-1][1] * merged[-1][0] == st:
            psz, pst = merged[-1]
            merged[-1] = (psz * sz, pst)
        else:
            merged.append((sz, st))
    if len(merged) > _MAX_RANK:
        raise RuntimeError("foreach_div_: unsupported tensor rank")
    # slots 7 .. 8-len hold innermost .. outermost
    dims = [1] * _MAX_RANK
    strs = [0] * _MAX_RANK
    for k, (sz, st) in enumerate(merged):
        dims[_MAX_RANK - 1 - k] = sz
        strs[_MAX_RANK - 1 - k] = st
    return dims, strs


def _launch_flat(t, other, is_f64):
    n = t.numel()
    _div_flat_kernel[(triton.cdiv(n, _BLOCK),)](
        t,
        other,
        n,
        IS_F64=is_f64,
        BLOCK=_BLOCK,
    )


def _launch_multi(chunk, other, is_f64):
    """One launch covering every contiguous tensor of ``chunk`` (<= _MAX_SLOTS).

    All slots share one dtype, so a tensor's base address is expressed as an
    element offset from the lowest-addressed tensor in the chunk; the kernel
    then keeps a single pointer argument and selects only integer offsets.
    """
    pad = _MAX_SLOTS - len(chunk)
    esz = chunk[0].element_size()
    ptrs = [t.data_ptr() for t in chunk]
    lo = min(ptrs)
    base = chunk[ptrs.index(lo)]
    deltas = [(p - lo) // esz for p in ptrs] + [0] * pad
    blocks = [triton.cdiv(t.numel(), _BLOCK) for t in chunk] + [0] * pad
    sizes = [t.numel() for t in chunk] + [0] * pad
    _div_multi_kernel[(sum(blocks),)](
        base,
        *deltas,
        other,
        *blocks,
        *sizes,
        IS_F64=is_f64,
        BLOCK=_BLOCK,
    )


# --------------------------------------------------------------------------- #
# entry point
# --------------------------------------------------------------------------- #
def foreach_div_tensor_(self, other):
    if not isinstance(other, torch.Tensor):
        raise TypeError("_foreach_div_.Tensor expects a Tensor divisor")
    if other.numel() != 1:
        raise RuntimeError("Tensor list must have a single element.")

    if self is None:
        return None

    y_f64 = other.dtype == torch.float64

    groups = {}
    strided = []
    for t in self:
        if not isinstance(t, torch.Tensor):
            raise TypeError("_foreach_div_.Tensor expects a list of Tensors")
        if t.numel() == 0:
            continue
        if t.is_contiguous():
            key = (t.dtype, t.device)
            bucket = groups.get(key)
            if bucket is None:
                groups[key] = [t]
            else:
                bucket.append(t)
        else:
            strided.append(t)

    for lst in groups.values():
        is_f64 = y_f64 or lst[0].dtype == torch.float64
        if len(lst) == 1:
            _launch_flat(lst[0], other, is_f64)
            continue
        if sum(t.numel() * t.element_size() for t in lst) > _FUSE_MAX_BYTES:
            # bandwidth-bound: the per-tensor kernel is faster per element
            for t in lst:
                _launch_flat(t, other, is_f64)
            continue
        for k in range(0, len(lst), _MAX_SLOTS):
            chunk = lst[k : k + _MAX_SLOTS]
            if len(chunk) == 1:
                _launch_flat(chunk[0], other, is_f64)
            else:
                _launch_multi(chunk, other, is_f64)

    for t in strided:
        n = t.numel()
        is_f64 = y_f64 or t.dtype == torch.float64
        dims, strs = _compact_dims(t)
        _div_strided_kernel[(triton.cdiv(n, _BLOCK_STRIDED),)](
            t,
            other,
            n,
            *dims,
            *strs,
            IS_F64=is_f64,
            BLOCK=_BLOCK_STRIDED,
        )
    return None
